<?php
namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; class xpath extends lib { var $guid = 'xpath'; var $xpath = null; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse'), 10, 3); } public function includes() { if (!$this->xpath) { require __DIR__ . DIRECTORY_SEPARATOR . '..' . DIRECTORY_SEPARATOR . 'classes' . DIRECTORY_SEPARATOR . 'class.xpath.php'; $this->xpath = new \qqworld_collector\module\engine\xpath; } } public function parse($html, $value, $index) { $this->includes(); $index = $index == 'all' ? 0 : $index; $this->xpath->loadHTML($html); $results = $this->xpath->query($value, $index); return $results; } } ?>